def collect(c):
 require(sha(PREVIOUS)==PREVIOUS_SHA,'Previous database changed');require(c.execute('SELECT count(*)FROM final_family_usable_keys').fetchone()[0]==41572,'Previous admissions changed');q=c.execute('SELECT * FROM final_family_numeric_queue ORDER BY book,row_number');names=[n[0]for n in q.description];data=[dict(zip(names,v))for v in q.fetchall()];require(len(data)==5641,'Previous queue changed');r=ExtendedResolver();rows=[];reviews=[];diag=[]
