  require(not c.execute("SELECT table_name FROM information_schema.tables WHERE table_name LIKE 'extended_family_%'").fetchall(),'Extended family namespace collision');rows,reviews,pages,diag=collect(c);c.execute('CREATE TABLE extended_family_observations AS SELECT * FROM final_family_observations WHERE false');c.execute('ALTER TABLE extended_family_observations ADD PRIMARY KEY(book,row_number)')
