  c.execute('CREATE TABLE extended_family_review(book VARCHAR,row_number INTEGER,status VARCHAR,PRIMARY KEY(book,row_number))');c.executemany('INSERT INTO extended_family_review VALUES(?,?,?)',reviews);c.execute('CREATE TABLE extended_family_pdf_evidence(book VARCHAR,page INTEGER,pdf_sha256 VARCHAR,text VARCHAR,PRIMARY KEY(book,page))')
