 with duckdb.connect(str(db),read_only=True)as c:rows=check_new(c);stats=c.execute('SELECT book,block,unit,quantity_role,count(*)FROM extended_family_observations GROUP BY ALL ORDER BY book,block').fetchall();review=c.execute("SELECT status,count(*)FROM extended_family_review WHERE status<>'usable_extended_family'GROUP BY ALL").fetchall();diagnostics=c.execute('SELECT count(*)FROM extended_family_diagnostics').fetchone()[0]
